const quote = ({ items }: QuoteStep): StepResult => {
  const totalBasePremium = items.reduce((total, item) => total + basePremiumOf(item), 0);

  return { premium: totalBasePremium + PROCESSING_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: [quote(scenario.steps[0] as QuoteStep)],
});
